// The SRD 5.2.1 spell list. Every spell is here so preparation / known counts
// are accurate; `build` is authored for the ones that do something in a fight.
// Class lists are a hand transcription of the SRD — spot-check before trusting
// an exotic assignment. Utility spells (no `build`) still occupy a prepared slot.

import type { Spell, SpellClass, SpellRole } from "./types";
import { atk, saveDmg, saveCond, effect, heal, conjure, cantripDice } from "./types";

const W: SpellClass = "wizard", S: SpellClass = "sorcerer", C: SpellClass = "cleric",
  D: SpellClass = "druid", B: SpellClass = "bard", K: SpellClass = "warlock",
  P: SpellClass = "paladin", R: SpellClass = "ranger", A: SpellClass = "artificer";

type Opt = {
  ct?: "action" | "bonus" | "reaction";
  conc?: boolean;
  rit?: boolean;
  role?: SpellRole;
  max?: number;
  build?: Spell["build"];
};

const S_ = (
  id: string, name: string, level: number,
  school: Spell["school"], classes: SpellClass[], o: Opt = {},
): Spell => ({
  id, name, level, school, classes,
  castTime: o.ct ?? "action",
  concentration: o.conc ?? false,
  ritual: o.rit,
  role: o.role ?? "utility",
  maxUpcast: o.max,
  build: o.build,
});

// cantrip damage that scales with character level
const cantripAtk = (die: number, dtype: Parameters<typeof saveDmg>[4]): Spell["build"] =>
  (c) => [{ type: "target", who: { who: "aiChoice" }, effects: [
    { type: "attack", bonus: c.toHit, onHit: [{ type: "damage", amount: `${cantripDice(c.casterLevel)}d${die}`, damageType: dtype }] },
  ] }];
const cantripSave = (ability: Parameters<typeof saveCond>[0], die: number, dtype: Parameters<typeof saveDmg>[4]): Spell["build"] =>
  (c) => [{ type: "target", who: { who: "aiChoice" }, effects: [
    { type: "save", ability, dc: c.dc, onFail: [{ type: "damage", amount: `${cantripDice(c.casterLevel)}d${die}`, damageType: dtype }] },
  ] }];

