export const SPELLS_BY_ID: Record<string, Spell> = Object.fromEntries(SPELLS.map((s) => [s.id, s]));

export function spellsForClass(cls: SpellClass): Spell[] {
  return SPELLS.filter((s) => s.classes.includes(cls));
}
